title <size:24>System Context View: Library</size>

set separator none
left to right direction

<style>
  root {
    BackgroundColor: #ffffff
    FontColor: #444444
  }
</style>

!include <C4/C4>
!include <C4/C4_Context>

Person(Patron, "Patron", $descr="Borrows books at the library.", $tags="", $link="")
System(Library, "Library", $descr="Manages books and loans.", $tags="", $link="")

Rel(Patron, Library, "Browses the catalogue through", $techn="HTTPS", $tags="", $link="")

SHOW_LEGEND(true)
hide stereotypes
@enduml`;

async function tryKroki() {
  const res = await fetch('https://kroki.io/plantuml/png', {
    method: 'POST',
    headers: { 'Content-Type': 'text/plain' },
    body: plantuml,
  });
  const ct = res.headers.get('content-type');
  const buf = await res.arrayBuffer();
  return { ok: res.ok, status: res.status, contentType: ct, bytes: buf.byteLength };
}

async function tryPlantuml() {
  // plantuml.com needs the custom-encoded path; just test reachability of the base
  const res = await fetch('https://www.plantuml.com/plantuml/');
  return { ok: res.ok, status: res.status };
}

const [kroki, plantuml] = await Promise.allSettled([tryKroki(), tryPlantuml()]);
return {
  kroki: kroki.status === 'fulfilled' ? kroki.value : String(kroki.reason),
  plantuml: plantuml.status === 'fulfilled' ? plantuml.value : String(plantuml.reason),
};

